# owner: platform
import unittest

from hourglass.rounding import round_labels, round_span, snap_minutes
from hourglass.parsing import parse_span
from hourglass.models import Span


class SnapTests(unittest.TestCase):
    def test_nearest_step(self):
        self.assertEqual(snap_minutes(62, 15), 60)
        self.assertEqual(snap_minutes(68, 15), 75)

    def test_exact_half_goes_up(self):
        self.assertEqual(snap_minutes(67 + 0, 15), 60 + 15)
        self.assertEqual(snap_minutes(15, 30), 30)

    def test_step_of_one_changes_nothing(self):
        self.assertEqual(snap_minutes(487, 1), 487)


class LabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("09:03-17:12")]
        self.assertEqual(round_labels(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_order_is_kept(self):
        spans = [parse_span("13:00-14:00"), parse_span("08:00-09:00")]
        labels = round_labels(spans, 30)
        self.assertEqual(labels, ["13:00-14:00 (1h 00m)", "08:00-09:00 (1h 00m)"])

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

    def test_end_of_day(self):
        spans = [parse_span("22:50-24:00")]
        self.assertEqual(round_labels(spans, 15), ["22:45-24:00 (1h 15m)"])

    def test_span_that_collapses_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(603, 606), 15)


class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        spans = [Span(540, 600)]
        for step in (0, -15, 7, 45, 90, 2.5, True):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_labels(spans, step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_all_divisors_of_an_hour_work(self):
        for step in (1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60):
            self.assertEqual(len(round_labels([Span(0, 1440)], step)), 1)
